require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';require_once __DIR__.'/../lib/notifications.php';
send_cors_headers();$context=require_admin('payouts.review');$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$stmt=$db->query('SELECT p.*,v.display_name,b.beneficiary_name,b.account_last4,b.bank_name,b.verification_status AS bank_status FROM payout_requests p JOIN vendors v ON v.id=p.vendor_id JOIN vendor_bank_accounts b ON b.id=p.bank_account_id ORDER BY p.requested_at DESC LIMIT 300');json_response(200,['success'=>true,'payouts'=>$stmt->fetchAll()]);}
if($method==='POST'){$body=get_json_body();$id=trim((string)($body['payout_id']??''));$action=trim((string)($body['action']??''));$reason=trim((string)($body['reason']??''));$reference=trim((string)($body['payment_reference']??''));if(!in_array($action,['maker_approve','checker_approve','reject','mark_paid','mark_failed'],true))json_response(422,['success'=>false,'message'=>'Invalid payout action.']);$next=['maker_approve'=>'maker_approved','checker_approve'=>'processing','reject'=>'rejected','mark_paid'=>'paid','mark_failed'=>'failed'][$action];$map=['requested'=>['maker_approved','rejected'],'maker_approved'=>['processing','rejected'],'processing'=>['paid','failed'],'failed'=>['processing']];if($next==='paid'&&mb_strlen($reference)<4)json_response(422,['success'=>false,'message'=>'Payment reference is required.']);$db->beginTransaction();try{$stmt=$db->prepare('SELECT * FROM payout_requests WHERE id=:id FOR UPDATE');$stmt->execute(['id'=>$id]);$payout=$stmt->fetch();if(!$payout)json_response(404,['success'=>false,'message'=>'Payout not found.']);assert_transition($payout['status'],$next,$map);if($action==='checker_approve'&&$payout['maker_admin_id']===$context['admin']['id'])json_response(409,['success'=>false,'message'=>'Maker and checker must be different administrators.']);$db->prepare('UPDATE payout_requests SET status=:status,maker_admin_id=IF(:action="maker_approve",:admin,maker_admin_id),maker_at=IF(:action="maker_approve",UTC_TIMESTAMP(),maker_at),checker_admin_id=IF(:action="checker_approve",:admin,checker_admin_id),checked_at=IF(:action="checker_approve",UTC_TIMESTAMP(),checked_at),payment_reference=IF(:status="paid",:reference,payment_reference),rejection_reason=IF(:status="rejected",:reason,rejection_reason),paid_at=IF(:status="paid",UTC_TIMESTAMP(),paid_at),updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['status'=>$next,'action'=>$action,'admin'=>$context['admin']['id'],'reference'=>$reference,'reason'=>$reason?:null,'id'=>$id]);if($next==='paid')$db->prepare('INSERT INTO vendor_ledger_entries (id,vendor_id,entry_type,amount,currency,balance_bucket,reference_type,reference_id,description,created_at) VALUES (:id,:vendor,"payout",:amount,"INR","paid","payout",:reference,"Vendor payout completed",UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'vendor'=>$payout['vendor_id'],'amount'=>-abs((float)$payout['amount']),'reference'=>$id]);create_notification('vendor',$payout['vendor_id'],'payout_update','Payout status updated','Your payout request is now '.str_replace('_',' ',$next).'.','../payouts.php',['payout_id'=>$id]);record_status_change('payout_request',$id,$payout['status'],$next,$reason?:null);audit_event('admin.payout_'.$action,'payout_request',$id,['payment_reference'=>$reference?:null]);$db->commit();json_response(200,['success'=>true,'message'=>'Payout status updated.','status'=>$next]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
